    assertEquals(28, nameRecords.size());
    NameRecord getResult = nameRecords.get(0);
    assertEquals("Copyright (c) 2007 Red Hat, Inc. All rights reserved. LIBERATION is a trademark of Red Hat, Inc.",
        getResult.getString());
